new=[
{'id':'OPSKILL-F019','severity':'high','title':'Check and inspect modes still mutate files','finding':'auto_learn accepts positional action check or inspect, but never reads args.action. Every action reaches execute_auto_learn_repair and the file write unless --dry-run was separately supplied. A caller selecting inspect can therefore trigger modifications from discovered or supplied remediation records.','evidence':[e(87,636,651),e(87,699,742),e(87,346,351)],'recommended_action':'Dispatch action explicitly; make check/inspect structurally read-only, including discovery outputs, and add a byte-preservation test for each mode.','validation':'OPSKILL-CHECK-015 confirms zero args.action reads after full-body review. No retained repair command executed.'},
{'id':'OPSKILL-F020','severity':'high','title':'Failed or unavailable repair verification becomes VERIFIED_CLEAN','finding':'Rollback requires both nonzero lint exit and parsed positive file-findings count. Missing checker, crash output, unparsed nonzero exit or an exception falls through; mypy return code is ignored unless stdout contains an error at a repaired line. The function then unconditionally labels the repair VERIFIED_CLEAN.','evidence':[e(86,96,103),e(87,366,407),e(87,408,446)],'recommended_action':'Require every mandatory verifier to run and return a valid bound success receipt; preserve unavailable/error status and restore exact bytes on any required-check failure.','validation':'OPSKILL-CHECK-016 demonstrates exit 2 plus no parsed count reaching VERIFIED_CLEAN in the isolated branch.'},
{'id':'OPSKILL-F021','severity':'high','title':'Repair destination is not confined to the declared repository or selected paths','finding':'Supplied remediation file values are normalized by lstrip and joined/resolved without an is_relative_to check; Windows absolute paths override repo_root. A direct-path fallback widens this further. Substring-based --files filtering is not exact path authorization.','evidence':[e(87,585,619),e(87,234,249),e(87,350,351)],'recommended_action':'Resolve and enforce an explicit owned-path allowlist, reject absolute/traversing and link-escaping inputs, and bind suggestions to exact current file hashes before any write.','validation':'OPSKILL-CHECK-017 is a pure Windows path calculation selecting C:/outside/file.md; no external file touched.'},
{'id':'OPSKILL-F022','severity':'high','title':'Repair rollback is lossy and unbound to current source bytes','finding':'Repair reads with errors=replace, uses text snapshots, ignores supplied matched_snippet/source identity and performs unguarded write_text. Invalid UTF-8 cannot be restored byte-for-byte, newline conventions can change, and intervening edits can be overwritten. Fixed discovery receipt paths may also supply stale suggestions after failed subprocesses.','evidence':[e(87,245,264),e(87,287,298),e(87,350,364),e(87,399,406),e(87,486,541),e(87,544,578)],'recommended_action':'Snapshot exact bytes, require strict decoding and current digest/snippet agreement, use unique bound discovery receipts and atomic compare-and-swap writes/rollback.','validation':'OPSKILL-CHECK-018 proves replacement-decoded bytes do not round-trip. No concurrent or filesystem mutation probe was run.'},
{'id':'OPSKILL-F023','severity':'medium','title':'Markdown marker repair consumes an empty bullet line ending','finding':'The repair regex uses whitespace classes that include newline. For an empty bullet line "* \\n", replacement yields "- " with no line ending; joining the lines can absorb the next line into the bullet despite the claimed minimal character change. Direct suggestions also do not revalidate code-fence context.','evidence':[e(87,78,91),e(87,287,298),e(87,331,344)],'recommended_action':'Restrict marker spacing to horizontal whitespace, preserve exact line terminators and revalidate Markdown context and current matched bytes.','validation':'OPSKILL-CHECK-019 independently evaluates the exact regex on the bounded empty-bullet input.'},
{'id':'OPSKILL-F024','severity':'medium','title':'Obstruction scanners label lexical graph diagnostics as mathematical exactness','finding':'The AST wrapper defines phi_1/gamma_2 as weighted counts of named import defects and sets is_exact/is_closed from zero counts; it supplies no cochain, differentials or exactness certificate. The ten-level companion checks filenames, heading presence and path/count existence, omitting promised semantic levels and most claimed invariants.','evidence':[e(88,18,54),e(89,99,151),e(90,37,98)],'recommended_action':'Use diagnostic names tied to the actual finite predicates, report unread/missing populations, and bind any cohomological interpretation to explicit carriers/maps/theorems rather than labels.','validation':'OPSKILL-CHECK-020 separates directed acyclicity from nonzero H1 of a triangular one-skeleton. No imported AST owner, Lean or native checker executed.'}
]
d={x['id']:x for x in r['findings']};d.update({x['id']:x for x in new});r['findings']=list(d.values());cp=H/(P+'_checks03.json');r['validation'].append({'kind':'bounded_independent_controls','path':str(cp.relative_to(H.parents[1])).replace('\\','/'),'sha256':hashlib.sha256(cp.read_bytes()).hexdigest(),'summary':'Six in-memory controls observed for parsed action use, failure flags, Windows paths, lossy rollback, Markdown newline and finite graph homology. No retained owner executed.'});p.write_text(json.dumps(r,indent=2)+'\n')
md=H/(P+'.md');s=md.read_text();s+='\nAuto-learn source adds actionable findings OPSKILL-F019--F023: inspection modes write, unavailable checks become clean, output paths are unconfined, rollback is lossy/unbound, and an empty Markdown bullet loses its newline. OPSKILL-F024 separates graph/lexical diagnostics from cohomological exactness. Six further in-memory controls confirm their bounded predicates.\n';md.write_text(s);print(json.dumps({'full':r['full_source_read_count'],'findings':len(r['findings'])}))
